func Deprecation(deprecatedAt time.Time, links ...string) func(http.Handler) http.Handler {
	if deprecatedAt.IsZero() {
		panic("middleware.Deprecation: deprecatedAt must not be zero")
	}

	// RFC 9745 uses a Structured Field Date (RFC 9651), not an HTTP-date.
	value := "@" + strconv.FormatInt(deprecatedAt.Unix(), 10)

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Deprecation", value)

			for _, link := range links {
				w.Header().Add("Link", link)
			}
			next.ServeHTTP(w, r)
		})
	}
}

func Sunset(sunsetAt time.Time, links ...string) func(http.Handler) http.Handler {
	if sunsetAt.IsZero() {
		panic("middleware.Sunset: sunsetAt must not be zero")
	}

	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			w.Header().Set("Sunset", sunsetAt.UTC().Format(http.TimeFormat))

			for _, link := range links {
				w.Header().Add("Link", link)
			}
			next.ServeHTTP(w, r)
		})
	}
}

func CleanPath(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		rctx := chi.RouteContext(r.Context())

		routePath := rctx.RoutePath
		if routePath == "" {
			if r.URL.RawPath != "" {
				routePath = r.URL.RawPath
			} else {
				routePath = r.URL.Path
			}
			rctx.RoutePath = path.Clean(routePath)
		}

		next.ServeHTTP(w, r)
	})
}

func Timeout(timeout time.Duration) func(next http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		fn := func(w http.ResponseWriter, r *http.Request) {
			ctx, cancel := context.WithTimeout(r.Context(), timeout)
			defer func() {
				cancel()
				if ctx.Err() == context.DeadlineExceeded {
					w.WriteHeader(http.StatusGatewayTimeout)
				}
			}()

			r = r.WithContext(ctx)
			next.ServeHTTP(w, r)
		}
		return http.HandlerFunc(fn)
	}
}

